result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "acct/accounts.py", "content": """"Chart of accounts: account types and their normal balances."""

from __future__ import annotations

from enum import Enum
from typing import Iterator


class AccountType(str, Enum):
    ASSET = "Asset"
    LIABILITY = "Liability"
    EQUITY = "Equity"
    REVENUE = "Revenue"
    EXPENSE = "Expense"


class Side(str, Enum):
    DEBIT = "Debit"
    CREDIT = "Credit"


#: Normal balance side for each account type.
NORMAL_BALANCE: dict[AccountType, Side] = {
    AccountType.ASSET: Side.DEBIT,
    AccountType.LIABILITY: Side.CREDIT,
    AccountType.EQUITY: Side.CREDIT,
    AccountType.REVENUE: Side.CREDIT,
    AccountType.EXPENSE: Side.DEBIT,
}


class Account:
    """A named account with a type. Balances live in the Journal, not here."""

    def __init__(self, name: str, acc_type: AccountType) -> None:
        if not isinstance(acc_type, AccountType):
            raise TypeError(f"acc_type must be an AccountType, got {acc_type!r}")
        self.name = name
        self.type = acc_type

    @property
    def normal_balance(self) -> Side:
        return NORMAL_BALANCE[self.type]

    @property
    def debit_positive(self) -> bool:
        """True if increases are recorded on the debit side."""
        return self.normal_balance is Side.DEBIT

    def __repr__(self) -> str:
        return f"Account({self.name!r}, {self.type})"


class AccountNotFound(KeyError):
    """Raised when an account name is not in the chart of accounts."""


class ChartOfAccounts:
    """Ordered registry of accounts, keyed by unique name."""

    def __init__(self) -> None:
        self._accounts: dict[str, Account] = {}

    def add(self, name: str, acc_type: AccountType) -> Account:
        if name in self._accounts:
            raise ValueError(f"account already exists: {name!r}")
        account = Account(name, acc_type)
        self._accounts[name] = account
        return account

    def get(self, name: str) -> Account:
        try:
            return self._accounts[name]
        except KeyError:
            raise AccountNotFound(f"unknown account: {name!r}") from None

    def __contains__(self, name: str) -> bool:
        return name in self._accounts

    def __iter__(self) -> Iterator[Account]:
        return iter(self._accounts.values())

    def __len__(self) -> int:
        return len(self._accounts)

    def of_type(self, *types: AccountType) -> list[Account]:
        return [a for a in self._accounts.values() if a.type in types]
